insert into private.rule_versions(domain,version,parameters,active_from)values('elo','elo-v1','{"initialRating":1500,"scale":400,"kFactor":32,"teamRating":"arithmetic_mean","rounding":"half_away_from_zero"}',now())on conflict(domain,version)do nothing;
create or replace function private.elo_expected(p_rating numeric,p_opponent numeric)returns numeric language sql immutable strict set search_path=pg_catalog as $$select 1::numeric/(1::numeric+power(10::numeric,(p_opponent-p_rating)/400::numeric))$$;
create or replace function private.elo_delta_v1(p_rating numeric,p_opponent numeric,p_winner_side smallint)returns numeric language sql immutable strict set search_path=pg_catalog,private as $$select round(32::numeric*((case when p_winner_side=1 then 1 else 0 end)::numeric-private.elo_expected(p_rating,p_opponent)))$$;
